/// Filters raw HTML in Markdown through a strict allowlist (`HTMLSanitizerPolicy`).
///
/// Only raw-HTML nodes (`htmlBlock`, `htmlInline`) are touched; markup generated by
/// `HTMLRenderer` is trusted. Raw HTML is tokenized and re-serialized from the parsed tokens:
/// the input string is never copied to the output. The output contains only escaped text and
/// allowlisted tags with allowlisted, re-escaped attributes, so a browser parsing it can't
/// see a tag, attribute, or comment that the sanitizer didn't write.
///
/// Defense in depth: this sanitizer is the primary control against hostile documents. The
/// viewer's strict Content-Security-Policy and disabled JavaScript (see `docs/VISION.md`) are
/// the backstop if it ever lets something through, not a reason to loosen it.
///
/// - Elements that run script or hold foreign content (`script`, `style`, `iframe`, …) are
///   removed with their content. Other unknown elements are removed but their text is kept.
///   Comments, doctypes, and processing instructions are removed.
/// - `on*` and `style` attributes are always removed. URL attributes must use an allowed
///   scheme (`http`, `https`, `mailto` for links) or be relative, after decoding character
///   references and ignoring whitespace and control characters.
/// - `id` and `name` values are prefixed with `user-content-` (as on GitHub) so raw HTML can't
///   collide with generated heading and footnote ids. (M2: in-document links to `#foo` should
///   also try `#user-content-foo`.)
/// - Tags are balanced per Markdown container. cmark splits raw HTML into separate nodes (an
///   inline `<span>`, text, then `</span>`; or HTML blocks around Markdown paragraphs), so the
///   sanitizer tracks open raw elements across the siblings of each container: an end tag
///   without a matching start tag in the same container is dropped, and elements still open
///   when the container ends are closed there. Raw HTML therefore can't close or escape the
///   paragraph, list item, block quote, or table cell it appears in. The footnote definitions
///   cmark moves to the end of the document count as a new container: the body's open
///   elements are closed before them, so they are never wrapped or dropped.
public struct HTMLSanitizer: Sendable {
    public init() {}

    /// Returns `root` with every raw-HTML node sanitized. Nodes that sanitize to nothing are
    /// removed, and siblings inside a dropped element (e.g. between inline `<script>` and
    /// `</script>`) are removed with it.
    public func sanitize(_ root: MarkdownNode) -> MarkdownNode {
        switch root.kind {
        case .htmlBlock(let html):
            return MarkdownNode(.htmlBlock(sanitize(fragment: html)), sourceRange: root.sourceRange)
        case .htmlInline(let html):
            return MarkdownNode(.htmlInline(sanitize(fragment: html)), sourceRange: root.sourceRange)
        default:
            return sanitizeTree(root)
        }
    }

    /// Sanitizes a standalone HTML fragment, closing any elements left open at its end.
    public func sanitize(fragment html: String) -> String {
        var sanitizer = RawHTMLSanitizer()
        return sanitizer.sanitize(html) + sanitizer.finish()
    }

    private struct Frame {
        var node: MarkdownNode
        var nextChild = 0
        var children: [MarkdownNode] = []
        var sanitizer = RawHTMLSanitizer()

        init(_ node: MarkdownNode) {
            self.node = node
            children.reserveCapacity(node.children.count)
        }
    }

    /// Rebuilds the tree with an explicit stack (no recursion), one `RawHTMLSanitizer` per
    /// container so tags balance within it.
    private func sanitizeTree(_ root: MarkdownNode) -> MarkdownNode {
        var stack = [Frame(root)]
        while let top = stack.indices.last {
            guard stack[top].nextChild < stack[top].node.children.count else {
                var frame = stack.removeLast()
                Self.closeOpenElements(in: &frame)
                var node = frame.node
                node.children = frame.children
                guard !stack.isEmpty else {
                    return node
                }
                stack[stack.count - 1].children.append(node)
                continue
            }
            let child = stack[top].node.children[stack[top].nextChild]
            stack[top].nextChild += 1
            switch child.kind {
            case .footnoteDefinition where stack[top].node.kind == .document:
                // cmark moves footnote definitions to the end of the document. Raw HTML in the
                // body must not wrap or hide them (and leave references dangling), so the body's
                // open elements are closed, and any dropping ends, before the first one.
                Self.closeOpenElements(in: &stack[top])
                stack.append(Frame(child))
            case .htmlBlock(let html):
                let clean = stack[top].sanitizer.sanitize(html)
                if clean.contains(where: { !$0.isWhitespace }) {
                    stack[top].children.append(MarkdownNode(.htmlBlock(clean), sourceRange: child.sourceRange))
                }
            case .htmlInline(let html):
                let clean = stack[top].sanitizer.sanitize(html)
                if !clean.isEmpty {
                    stack[top].children.append(MarkdownNode(.htmlInline(clean), sourceRange: child.sourceRange))
                }
            case .image:
                // Alt text is rendered as escaped plain text, never as markup.
                if !stack[top].sanitizer.isDroppingContent {
                    stack[top].children.append(child)
                }
            default:
                if stack[top].sanitizer.isDroppingContent {
                    continue
                }
                if child.children.isEmpty {
                    stack[top].children.append(child)
                } else {
                    stack.append(Frame(child))
                }
            }
        }
        return root
    }

    /// Appends end tags for the raw elements still open in `frame` and resets its sanitizer.
    private static func closeOpenElements(in frame: inout Frame) {
        let closers = frame.sanitizer.finish()
        frame.sanitizer = RawHTMLSanitizer()
        if !closers.isEmpty {
            let kind: MarkdownNode.Kind =
                holdsBlocks(frame.node.kind) ? .htmlBlock(closers + "\n") : .htmlInline(closers)
            frame.children.append(MarkdownNode(kind))
        }
    }

    /// Whether a node's children are blocks (so closing tags go in an HTML block).
    private static func holdsBlocks(_ kind: MarkdownNode.Kind) -> Bool {
        switch kind {
        case .document, .blockQuote, .list, .item, .taskItem, .footnoteDefinition: true
        default: false
        }
    }
}

/// Sanitizes a sequence of raw-HTML strings that share one container, keeping track of open
/// elements and of content being dropped between calls.
struct RawHTMLSanitizer {
    private struct Drop {
        let name: String
        let isRawText: Bool
        var depth = 1
    }

    private var openElements: [String] = []
    /// How many of each element are in `openElements`, so lookups don't scan a deep stack.
    private var openCounts: [String: Int] = [:]
    private var dropping: Drop?

    /// Inside an element removed with its content; non-HTML siblings must be skipped.
    var isDroppingContent: Bool {
        dropping != nil
    }

    mutating func sanitize(_ html: String) -> String {
        var output = ""
        var tokenizer = HTMLTokenizer(html)
        while true {
            if var drop = dropping {
                if drop.isRawText {
                    guard tokenizer.skipRawText(endTag: drop.name) else {
                        break
                    }
                    dropping = nil
                    continue
                }
                guard let token = tokenizer.next() else {
                    break
                }
                switch token {
                case .startTag(let tag) where tag.name == drop.name && !tag.isSelfClosing:
                    drop.depth += 1
                case .endTag(let name) where name == drop.name:
                    drop.depth -= 1
                default:
                    break
                }
                dropping = drop.depth > 0 ? drop : nil
                continue
            }
            guard let token = tokenizer.next() else {
                break
            }
            switch token {
            case .text(let text):
                HTMLEscaping.appendText(text, to: &output)
            case .comment:
                break
            case .startTag(let tag):
                startTag(tag, into: &output)
            case .endTag(let name):
                endTag(name, into: &output)
            }
        }
        return output
    }

    /// Ends the container: returns end tags for every element still open, and stops dropping.
    mutating func finish() -> String {
        let closers = openElements.reversed().map { "</\($0)>" }.joined()
        openElements.removeAll()
        openCounts.removeAll()
        dropping = nil
        return closers
    }

    private mutating func startTag(_ tag: HTMLStartTag, into output: inout String) {
        typealias Policy = HTMLSanitizerPolicy
        if Policy.rawTextElements.contains(tag.name) {
            // A browser ignores `/>` on these, so `<script/>` still starts a script.
            dropping = Drop(name: tag.name, isRawText: true)
            return
        }
        if Policy.contentDroppingElements.contains(tag.name) {
            if !tag.isSelfClosing {
                dropping = Drop(name: tag.name, isRawText: false)
            }
            return
        }
        guard Policy.elements.contains(tag.name) else {
            return
        }
        if let ancestors = Policy.requiredAncestors[tag.name],
            !ancestors.contains(where: { openCounts[$0, default: 0] > 0 })
        {
            return
        }
        output += "<\(tag.name)"
        output += Self.attributes(of: tag)
        if Policy.voidElements.contains(tag.name) {
            output += tag.isSelfClosing ? " />" : ">"
        } else {
            // `/>` on a non-void element is ignored by browsers: it's a start tag.
            output += ">"
            openElements.append(tag.name)
            openCounts[tag.name, default: 0] += 1
        }
    }

    private mutating func endTag(_ name: String, into output: inout String) {
        guard openCounts[name, default: 0] > 0, let index = openElements.lastIndex(of: name) else {
            return
        }
        for element in openElements[index...].reversed() {
            output += "</\(element)>"
            openCounts[element, default: 0] -= 1
        }
        openElements.removeSubrange(index...)
    }

    private static func attributes(of tag: HTMLStartTag) -> String {
        typealias Policy = HTMLSanitizerPolicy
        var output = ""
        for attribute in tag.attributes where Policy.allowsAttribute(attribute.name, on: tag.name) {
            let isPrefixed = Policy.prefixedAttributes.contains(attribute.name)
            guard let raw = attribute.value else {
                if !isPrefixed {
                    output += " \(attribute.name)"
                }
                continue
            }
            let value = AttributeValue(raw)
            if let schemes = Policy.urlSchemes[tag.name]?[attribute.name] {
                let urls = attribute.name == "srcset" ? URLSchemePolicy.srcsetURLs(value.decoded) : [value.decoded]
                guard urls.allSatisfy({ URLSchemePolicy.allows($0, schemes: schemes) }) else {
                    continue
                }
            }
            var serialized = value.serialized
            if isPrefixed {
                guard !value.decoded.isEmpty else {
                    continue
                }
                if !value.decoded.hasPrefix(Policy.userContentPrefix) {
                    serialized = Policy.userContentPrefix + serialized
                }
            }
            output += " \(attribute.name)=\"\(serialized)\""
        }
        return output
    }
}

/// URL scheme checks for sanitized attributes.
enum URLSchemePolicy {
    /// Whether `url` (with character references already decoded) is relative or uses one of
    /// `schemes`.
    ///
    /// Stricter than a URL parser on purpose, like the `sanitize` gem: every character up to
    /// U+0020 and DEL is removed first (browsers strip tab and newlines anywhere and leading
    /// controls), and then anything before a `:` that comes before the first `/`, `?`, or `#`
    /// is the scheme and must be allowlisted. So `jav&#x09;ascript:`, ` javascript:`, and even
    /// `foo bar:x` are rejected, and `/a:b`, `?a:b`, and `#a:b` are relative.
    static func allows(_ url: String, schemes: Set<String>) -> Bool {
        var scheme = ""
        for scalar in url.unicodeScalars where scalar.value > 0x20 && scalar.value != 0x7F {
            switch scalar {
            case ":":
                return schemes.contains(scheme.lowercased())
            case "/", "?", "#":
                return true
            default:
                scheme.unicodeScalars.append(scalar)
            }
        }
        return true
    }

    /// Every comma- or whitespace-separated piece of a `srcset`, so each URL is checked
    /// whatever the descriptors are. Over-splitting only makes the check stricter.
    static func srcsetURLs(_ srcset: String) -> [String] {
        srcset.split { $0 == "," || $0.isWhitespace }.map(String.init)
    }
}
